/**
 * Token-bucket rate limiter, decoupled from Express and from the clock.
 *
 * - `capacity`      max tokens in the bucket
 * - `refillPerSec`  tokens added per second (continuous refill)
 * - `now()`         injectable clock (seconds or ms — see timeUnit); pass a
 *                   controllable function in tests to drive time deterministically.
 * - `keyFn(req)`    extracts the bucket key from a request (default: IP)
 */

/**
 * Core bucket logic. Returns whether a request with `cost` tokens is admitted,
 * mutating the bucket state.
 */
function tryTake(bucket, capacity, refillPerSec, now, cost = 1) {
  const t = now();
  if (bucket.last == null) bucket.last = t;

  // Refill continuously based on elapsed time.
  const elapsed = Math.max(0, t - bucket.last);
  bucket.tokens = Math.min(capacity, bucket.tokens + elapsed * refillPerSec);
  bucket.last = t;

  if (bucket.tokens >= cost) {
    bucket.tokens -= cost;
    return { allowed: true, remaining: Math.floor(bucket.tokens) };
  }

  // Seconds until enough tokens accumulate for `cost`.
  const deficit = cost - bucket.tokens;
  return {
    allowed: false,
    remaining: 0,
    retryAfter: deficit / refillPerSec,
  };
}

/**
 * Creates an Express middleware.
 *
 * Options:
 *   capacity     (default 5)
 *   refillPerSec (default 1)
 *   now          injectable clock function (default Date.now; values in ms
 *                are normalized internally — any monotonic unit works since
 *                refill math is unit-relative, but keep it consistent)
 *   keyFn        (req) => key, default req.ip
 *   timeUnit     'ms' (default) or 's' — unit returned by now()
 */
function createRateLimiter(options = {}) {
  const {
    capacity = 5,
    refillPerSec = 1,
    now = () => Date.now(),
    timeUnit = 'ms',
    keyFn = (req) => req.ip,
  } = options;

  if (typeof now !== 'function') {
    throw new TypeError('now must be a function');
  }
  if (timeUnit !== 'ms' && timeUnit !== 's') {
    throw new TypeError("timeUnit must be 'ms' or 's'");
  }

  // Normalize to seconds for all internal math.
  const toSeconds = timeUnit === 'ms' ? (v) => v / 1000 : (v) => v;
  const buckets = new Map();

  function middleware(req, res, next) {
    const key = keyFn(req);
    let bucket = buckets.get(key);
    if (!bucket) {
      bucket = { tokens: capacity, last: null };
      buckets.set(key, bucket);
    }

    const result = tryTake(
      bucket,
      capacity,
      refillPerSec,
      () => toSeconds(now()),
      1
    );

    res.set('X-RateLimit-Limit', String(capacity));
    res.set('X-RateLimit-Remaining', String(result.remaining));

    if (result.allowed) return next();

    const resetEpoch = toSeconds(now()) + result.retryAfter;
    res.set('X-RateLimit-Reset', String(Math.ceil(resetEpoch)));
    res.set('Retry-After', String(Math.ceil(result.retryAfter)));
    return res.status(429).json({ error: 'Too Many Requests' });
  }

  middleware.buckets = buckets; // exposed for tests/inspection
  return middleware;
}

module.exports = { createRateLimiter, tryTake };
