const express = require('express');
const supertest = require('supertest');
const { test } = require('node:test');
const assert = require('node:assert');
const { createRateLimiter } = require('./token-bucket');

/**
 * Deterministic fake clock for tests. `now()` is injectable into the
 * middleware so tests control time exactly.
 */
function fakeClock(startSeconds = 0) {
  let t = startSeconds;
  return {
    now: () => t,
    advance(seconds) {
      t += seconds;
    },
  };
}

function buildApp(clock) {
  const app = express();
  app.use(
    createRateLimiter({
      capacity: 5,
      refillPerSec: 1,
      now: clock.now,
      timeUnit: 's',
      keyFn: (req) => req.ip,
    })
  );
  app.get('/', (req, res) => res.status(200).json({ ok: true }));
  return app;
}

test('burst of 5 requests passes, with correct headers', async () => {
  const clock = fakeClock();
  const app = buildApp(app_clock_placeholder(clock));
  function app_clock_placeholder(c) { return c; }
  for (let i = 0; i < 5; i++) {
    const res = await supertest(app).get('/').set('X-Forwarded-For', '10.0.0.1');
    assert.strictEqual(res.status, 200);
    assert.strictEqual(res.headers['x-ratelimit-limit'], '5');
    assert.strictEqual(res.headers['x-ratelimit-remaining'], String(4 - i));
  }
});

test('6th request in burst is 429 with X-RateLimit-Reset', async () => {
  const clock = fakeClock(1000);
  const app = buildApp(clock);
  for (let i = 0; i < 5; i++) {
    const res = await supertest(app).get('/').set('X-Forwarded-For', '10.0.0.2');
    assert.strictEqual(res.status, 200);
  }
  const res = await supertest(app).get('/').set('X-Forwarded-For', '10.0.0.2');
  assert.strictEqual(res.status, 429);
  assert.strictEqual(res.headers['x-ratelimit-limit'], '5');
  assert.strictEqual(res.headers['x-ratelimit-remaining'], '0');
  // Bucket empty at t=1000; next token at t=1001.
  assert.strictEqual(res.headers['x-ratelimit-reset'], '1001');
});

test('advancing fake time by 3s admits exactly 3 more (then 429 again)', async () => {
  const clock = fakeClock(0);
  const app = buildApp(clock);

  // Drain the bucket.
  for (let i = 0; i < 5; i++) {
    await supertest(app).get('/').set('X-Forwarded-For', '10.0.0.3');
  }
  let res = await supertest(app).get('/').set('X-Forwarded-For', '10.0.0.3');
  assert.strictEqual(res.status, 429);

  // Refill 3 tokens over 3 seconds.
  clock.advance(3);

  for (let i = 0; i < 3; i++) {
    res = await supertest(app).get('/').set('X-Forwarded-For', '10.0.0.3');
    assert.strictEqual(res.status, 200, `request ${i + 1} after refill`);
    assert.strictEqual(res.headers['x-ratelimit-remaining'], String(2 - i));
  }

  // The 4th request after refill must be rejected — exactly 3 admitted.
  res = await supertest(app).get('/').set('X-Forwarded-For', '10.0.0.3');
  assert.strictEqual(res.status, 429);
  // Partial refill happened during the 3 admitted requests? No time advanced,
  // so reset should be ~1s away.
  assert.ok(Number(res.headers['x-ratelimit-reset']) > 0);
});

test('buckets are keyed by IP independently', async () => {
  const clock = fakeClock(0);
  const app = buildApp(clock);
  for (let i = 0; i < 5; i++) {
    const a = await supertest(app).get('/').set('X-Forwarded-For', '10.0.0.4');
    assert.strictEqual(a.status, 200);
  }
  // Different IP unaffected.
  const b = await supertest(app).get('/').set('X-Forwarded-For', '10.0.0.5');
  assert.strictEqual(b.status, 200);
  // Original IP now limited.
  const c = await supertest(app).get('/').set('X-Forwarded-For', '10.0.0.4');
  assert.strictEqual(c.status, 429);
});
